 if p.suffix=='.json':
  def walk(o):
   if isinstance(o,dict):
    for k,v in o.items():
     if k=='profile_lookups' and isinstance(v,list):
      for r in v:services.append((m['file_id'],r))
     walk(v)
   elif isinstance(o,list):
    for v in o:walk(v)
